function evalRPN(tokens) {
  const stack = []
  for (const t of tokens) {
    if (!['+', '-', '*', '/'].includes(t)) {
      stack.push(Number(t))
      continue
    }
    const b = stack.pop()
    const a = stack.pop()
    if (t === '+') stack.push(a + b)
    else if (t === '-') stack.push(a - b)
    else if (t === '*') stack.push(a * b)
    else {
      if (b === 0) throw new Error('除数不能为 0（Java 整数除法会抛 ArithmeticException）')
      stack.push(Math.trunc(a / b))
    }
  }
  return stack[0]
