    same(r.capacity, 15)
    same(r.grows, 1)
  })
  check('连续扩容次数与容量序列正确', () => {
    const r = simulateArrayList(10, 23)
    same(r.capacity, 33, '10→15→22→33')
    same(r.grows, 3)
  })
