function recommendPoolSize(spec) {
  const { cpu, ioWaitRatio } = spec
  const ratio = ioWaitRatio >= 0 && ioWaitRatio <= 1 ? ioWaitRatio : 0
  return { core: Math.max(1, Math.round(cpu / (1 - ratio))) }
}

